import React,{act,StrictMode,useLayoutEffect} from 'react';
import {createRoot,type Root} from 'react-dom/client';
import {App} from 'm928-continuation-app';
import type {NamingSession,GenerateResult} from '../../src/shared/types';
import type {CulturalWorkflowAPI,CulturalComparisonRead} from '../../src/shared/cultural-workflow-api';
import type {CulturalComparisonCatalogAPI,CulturalComparisonCatalogPage,CulturalComparisonCatalogRequest} from '../../src/shared/cultural-comparison-catalog';
